), updated AS (
  UPDATE public.hospitals h
  SET
    name = nhia_hcps.name,
    address = NULLIF(nhia_hcps.address, ''),
    state = NULLIF(nhia_hcps.state, ''),
    is_active = true,
    updated_at = now()
  FROM nhia_hcps
  WHERE h.code = nhia_hcps.code
  RETURNING h.code
)
INSERT INTO public.hospitals (code, name, address, state, is_active)
SELECT nhia_hcps.code, nhia_hcps.name, NULLIF(nhia_hcps.address, ''), NULLIF(nhia_hcps.state, ''), true
FROM nhia_hcps
WHERE NOT EXISTS (
  SELECT 1 FROM updated WHERE updated.code = nhia_hcps.code
)
AND NOT EXISTS (
  SELECT 1 FROM public.hospitals h WHERE h.code = nhia_hcps.code
);
